import math
R=10.0; r=1.6; d=3.45; p=9.4; N=6.0; e=0.9
def rate(t):
    # pitch per turn as function of turn count t
    def s(x):
        x=min(max(x,0),1); return x*x*(3-2*x)
    if t<N/2:
        return d+(p-d)*s((t-e*0.5)/e)
    return d+(p-d)*s((N-t-e*0.5)/e)
pts=[]; z=0.0; n=int(N*36); dt=N/n
for i in range(n+1):
    t=i*dt; a=2*math.pi*t
    pts.append(cq.Vector(R*math.cos(a),R*math.sin(a),z))
    z+=rate(t+dt/2)*dt
path=cq.Wire.assembleEdges([cq.Edge.makeSpline(pts)])
prof=cq.Workplane("XZ").center(R,0).circle(r)
result=prof.sweep(cq.Workplane().add(path),isFrenet=True)

